SELECT CAST(json_object('workItemId',m.work_item_id,'operationId',m.operation_id,'serviceId',m.service_id,'kind',m.kind,'requestJson',m.request_json,'requestDigest',m.request_digest,'state',m.state,'resultJson',m.result_json,'batches',json((SELECT json_group_array(json_object('batchId',b.batch_id,'serviceId',b.service_id,'digest',b.digest,'frozenBytes',b.frozen_bytes,'ackedAtMs',b.acked_at_ms)) FROM (SELECT * FROM automation_batches ORDER BY batch_id) b WHERE EXISTS (SELECT 1 FROM json_each(CASE WHEN json_valid(b.frozen_bytes) THEN b.frozen_bytes ELSE '{}' END,'$.entries') e WHERE json_extract(e.value,'$.kind')='sessionCreate' AND json_extract(e.value,'$.value.workItemId')=m.work_item_id)))) AS TEXT) AS observation FROM machine_work_items m WHERE m.work_item_id=?;
